-- ROLLBACK of 11: removes only the draft set versions created for these sets (no attempts can reference a draft). Published sets untouched.
-- generated by scripts/prod-open/sat-expand-sql.ts (SAT_11=1). Run: npx supabase db query --linked -f <this file>. Idempotent; drafts only (never published here); published sets/attempts untouched.

do $rb11$ declare v_n int; begin
  delete from mock_exam_sets s where s.status = 'draft' and s.name = any (array['SAT Practice Test 1','SAT Practice Test 2','SAT Practice Test 3','SAT Practice Test 10','SAT Practice Test 16','SAT Practice Test 19','SAT Practice Test 21','SAT Practice Test 23']) and not exists (select 1 from mock_exam_attempts a where a.exam_set_id = s.id)
    and exists (select 1 from mock_exam_sets p where p.set_group_id = s.set_group_id and p.status = 'published' and p.version_no < s.version_no);
  get diagnostics v_n = row_count; raise notice 'draft set versions removed: %', v_n;
end $rb11$;
